package ru.hryushki.accounts;
import org.json.*;
import java.util.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
public final class SyncModel {
 static final String[] LISTS={"operations","products","materials"},KINDS={"operation","product","material"};
 public static String canonical(Object x)throws JSONException{if(x==null||x==JSONObject.NULL)return "null";if(x instanceof JSONObject){JSONObject o=(JSONObject)x;List<String> keys=new ArrayList<>();Iterator<String> it=o.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys);List<String> parts=new ArrayList<>();for(String k:keys)parts.add(JSONObject.quote(k)+":"+canonical(o.get(k)));return "{"+String.join(",",parts)+"}";}if(x instanceof JSONArray){List<String> a=new ArrayList<>();JSONArray r=(JSONArray)x;for(int i=0;i<r.length();i++)a.add(canonical(r.get(i)));return "["+String.join(",",a)+"]";}if(x instanceof Number)return new BigDecimal(x.toString()).stripTrailingZeros().toPlainString();if(x instanceof Boolean)return x.toString();return JSONObject.quote(String.valueOf(x));}
 static boolean equal(Object a,Object b)throws JSONException{return canonical(a).equals(canonical(b));}
 static String hash(String s)throws Exception{StringBuilder b=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)))b.append(String.format(Locale.ROOT,"%02x",v));return b.toString();}
 public static void ids(JSONObject d,boolean initial)throws Exception{for(int j=0;j<LISTS.length;j++)for(JSONObject o:Engine.list(Engine.rows(d,LISTS[j])))if(Engine.s(o,"_syncId","").isEmpty())o.put("_syncId",initial?(j==0?"legacy-op-"+o.getLong("id"):KINDS[j]+"-"+hash(o.getString("name"))):KINDS[j]+"-"+UUID.randomUUID());}
 public static JSONObject attach(JSONObject d,String owner)throws Exception{JSONObject n=Engine.copy(d);JSONObject m=n.optJSONObject("_sync");Engine.require(m==null||m.optString("owner").equals(owner),"База привязана к другому аккаунту. Используйте пустую тестовую базу");if(m==null){ids(n,true);m=new JSONObject();m.put("owner",owner);m.put("base",new JSONObject());m.put("conflicts",new JSONArray());n.put("_sync",m);}return n;}
 public static Map<String,JSONObject> records(JSONObject d)throws Exception{Map<String,JSONObject> out=new LinkedHashMap<>();for(int j=0;j<LISTS.length;j++)for(JSONObject original:Engine.list(Engine.rows(d,LISTS[j]))){JSONObject o=Engine.copy(original);String id=o.optString("_syncId");Engine.require(!id.isEmpty(),"Запись без идентификатора синхронизации");if(j==0)o.remove("id");JSONObject r=new JSONObject();r.put("kind",KINDS[j]);r.put("key",id);r.put("data",o);String key=KINDS[j]+"|"+id;Engine.require(!out.containsKey(key),"Повтор идентификатора синхронизации");out.put(key,r);}return out;}
 static String key(JSONObject r){return r.optString("kind")+"|"+r.optString("key");}
 public static class Request {public JSONObject snapshot;public JSONArray changes;public Map<String,JSONObject> all;public Set<String> sent=new HashSet<>();}
 public static Request request(JSONObject d,String owner)throws Exception{Engine.require(d.optJSONObject("_sync")!=null&&d.getJSONObject("_sync").optString("owner").equals(owner),"Сначала подключите эту тестовую базу");Engine.require(Engine.rows(d.getJSONObject("_sync"),"conflicts").length()==0,"Есть конфликт. Выберите вариант в разделе синхронизации");Request q=new Request();q.snapshot=Engine.copy(d);q.all=records(d);q.changes=new JSONArray();JSONObject base=d.getJSONObject("_sync").getJSONObject("base");for(Map.Entry<String,JSONObject> e:q.all.entrySet()){JSONObject b=base.optJSONObject(e.getKey());if(b==null||!equal(b.opt("data"),e.getValue().get("data"))){if(q.changes.length()==400)break;JSONObject c=Engine.copy(e.getValue());c.put("base_version",b==null?0:b.optLong("version"));q.changes.put(c);q.sent.add(e.getKey());}}return q;}
 static void put(JSONObject d,JSONObject r)throws Exception{String kind=r.getString("kind"),id=r.getString("key");int which=Arrays.asList(KINDS).indexOf(kind);Engine.require(which>=0,"Неизвестный тип ответа сервера");JSONArray a=Engine.rows(d,LISTS[which]);JSONObject payload=Engine.copy(r.getJSONObject("data"));payload.put("_syncId",id);int index=-1;long max=0;for(int i=0;i<a.length();i++){JSONObject row=a.getJSONObject(i);max=Math.max(max,row.optLong("id"));if(row.optString("_syncId").equals(id))index=i;}if(which==0)payload.put("id",index<0?max+1:a.getJSONObject(index).getLong("id"));if(index<0)a.put(payload);else a.put(index,payload);d.put(LISTS[which],a);}
 public static JSONObject merge(JSONObject fresh,Request q,JSONObject reply,String owner)throws Exception{Engine.require(reply.optString("owner").equals(owner),"Ответ относится к другому аккаунту");JSONObject n=Engine.copy(fresh),meta=n.getJSONObject("_sync"),base=meta.getJSONObject("base"),oldBase=q.snapshot.getJSONObject("_sync").getJSONObject("base");Map<String,JSONObject> current=records(n);JSONArray conflicts=new JSONArray();boolean ok=reply.optBoolean("ok");
  for(JSONObject r:Engine.list(Engine.rows(reply,"records"))){String k=key(r);JSONObject local=current.get(k),old=oldBase.optJSONObject(k),requested=q.all.get(k);Object data=r.get("data"),oldData=old==null?null:old.opt("data");boolean ack=ok&&q.sent.contains(k);if(ack){if(local==null||requested!=null&&equal(local.get("data"),requested.get("data")))put(n,r);base.put(k,r);}
   else if(local==null||equal(local.get("data"),oldData)){put(n,r);base.put(k,r);}
   else if(equal(local.get("data"),data)||equal(data,oldData)){base.put(k,r);}
   else{JSONObject conflict=Engine.copy(r);conflict.put("local",local.get("data"));conflicts.put(conflict);}
  }
  meta.put("conflicts",conflicts);meta.put("lastSync",Engine.now());Engine.validate(n);unique(n);return n;
 }
 static void unique(JSONObject d){for(String list:new String[]{"products","materials"}){Set<String> names=new HashSet<>();for(JSONObject o:Engine.list(Engine.rows(d,list)))Engine.require(names.add(o.optString("name").toLowerCase(Locale.ROOT)),"Совпали названия карточек. Обмен остановлен");}}
 public static JSONObject resolve(JSONObject d,int index,boolean useRemote)throws Exception{JSONObject n=Engine.copy(d),m=n.getJSONObject("_sync");JSONArray conflicts=m.getJSONArray("conflicts");JSONObject r=conflicts.getJSONObject(index);if(useRemote)put(n,r);JSONObject b=Engine.copy(r);b.remove("local");m.getJSONObject("base").put(key(r),b);conflicts.remove(index);Engine.validate(n);return n;}
}
